.index-hero {
      background: linear-gradient(135deg, var(--color-primary-light) 0%, #f0f4ff 100%);
      padding: var(--spacing-2xl) 0;
    }

    .index-hero .container {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: var(--spacing-xl);
      align-items: center;
    }

    .index-hero-content {
      display: flex;
      flex-direction: column;
      justify-content: center;
    }

    .index-hero-content h1 {
      color: var(--color-primary-dark);
      margin-bottom: var(--spacing-md);
    }

    .index-hero-subtitle {
      font-size: 1.1rem;
      color: var(--color-text-light);
      margin-bottom: var(--spacing-lg);
    }

    .index-hero-btn {
      align-self: flex-start;
      min-width: 200px;
    }

    .index-hero-image {
      width: 100%;
      height: auto;
      border-radius: 12px;
      box-shadow: 0 8px 24px rgba(0, 0, 0, 0.15);
    }

    .index-overview {
      padding: var(--spacing-2xl) 0;
      background-color: var(--color-bg);
    }

    .index-overview h2 {
      text-align: center;
      color: var(--color-primary-dark);
      margin-bottom: var(--spacing-xl);
    }

    .index-features {
      gap: var(--spacing-lg);
    }

    .index-feature-card {
      text-align: center;
      border: none;
      box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
    }

    .index-feature-card h3 {
      color: var(--color-primary-dark);
    }

    .index-curriculum-section {
      padding: var(--spacing-2xl) 0;
      background-color: var(--color-bg-light);
    }

    .index-curriculum-section h2 {
      color: var(--color-primary-dark);
      text-align: center;
      margin-bottom: var(--spacing-md);
    }

    .index-curriculum-intro {
      text-align: center;
      color: var(--color-text-light);
      margin-bottom: var(--spacing-xl);
      font-size: 1.1rem;
    }

    .index-modules {
      max-width: 900px;
      margin: 0 auto;
    }

    .index-module {
      margin-bottom: var(--spacing-md);
      border: 1px solid var(--color-border);
      border-radius: 8px;
      background-color: var(--color-bg);
      overflow: hidden;
    }

    .index-module-header {
      display: flex;
      align-items: center;
      gap: var(--spacing-md);
      padding: var(--spacing-md) var(--spacing-lg);
      cursor: pointer;
      font-weight: 600;
      font-size: 1.1rem;
      color: var(--color-text);
      background-color: var(--color-bg);
      border: none;
      width: 100%;
      text-align: left;
      transition: var(--transition);
    }

    .index-module-header:hover {
      background-color: var(--color-primary-light);
    }

    .index-module-header:focus-visible {
      outline: 3px solid var(--color-accent);
      outline-offset: -3px;
    }

    .index-module-number {
      display: flex;
      align-items: center;
      justify-content: center;
      min-width: 40px;
      width: 40px;
      height: 40px;
      background-color: var(--color-primary-dark);
      color: var(--color-text-on-dark);
      border-radius: 50%;
      font-weight: 700;
    }

    .index-module-title {
      flex: 1;
      color: var(--color-primary-dark);
    }

    .index-module[open] .index-module-header {
      background-color: var(--color-primary-light);
      border-bottom: 2px solid var(--color-primary-dark);
    }

    .index-module-content {
      padding: var(--spacing-lg);
      background-color: var(--color-bg);
      border-top: 2px solid var(--color-border);
    }

    .index-module-content p {
      margin-bottom: var(--spacing-md);
      color: var(--color-text-light);
    }

    .index-module-list {
      list-style: none;
      padding: 0;
    }

    .index-module-list li {
      padding: var(--spacing-xs) 0;
      padding-left: var(--spacing-lg);
      position: relative;
      color: var(--color-text-light);
    }

    .index-module-list li::before {
      content: "✓";
      position: absolute;
      left: 0;
      color: var(--color-success);
      font-weight: 700;
    }

    .index-testimonials-section {
      padding: var(--spacing-2xl) 0;
      background-color: var(--color-bg);
    }

    .index-testimonials-section h2 {
      color: var(--color-primary-dark);
      text-align: center;
      margin-bottom: var(--spacing-md);
    }

    .index-testimonials-intro {
      text-align: center;
      color: var(--color-text-light);
      margin-bottom: var(--spacing-xl);
      font-size: 1.1rem;
    }

    .index-testimonials {
      gap: var(--spacing-lg);
    }

    .index-testimonial-card {
      display: flex;
      flex-direction: column;
      border: 1px solid var(--color-border);
      box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
    }

    .index-testimonial-stars {
      color: #ffc107;
      font-size: 1.1rem;
      margin-bottom: var(--spacing-md);
      letter-spacing: 0.1em;
    }

    .index-testimonial-text {
      flex: 1;
      color: var(--color-text-light);
      margin-bottom: var(--spacing-md);
      font-style: italic;
    }

    .index-testimonial-author {
      border-top: 1px solid var(--color-border);
      padding-top: var(--spacing-md);
    }

    .index-author-name {
      font-weight: 700;
      color: var(--color-primary-dark);
      margin-bottom: var(--spacing-xs);
    }

    .index-author-role {
      font-size: 0.9rem;
      color: var(--color-text-light);
      margin: 0;
    }

    .index-enroll-section {
      background: linear-gradient(135deg, var(--color-primary-dark) 0%, #002a52 100%);
      padding: var(--spacing-2xl) 0;
      text-align: center;
    }

    .index-enroll-content {
      max-width: 800px;
      margin: 0 auto;
    }

    .index-enroll-content h2 {
      color: var(--color-text-on-dark);
      margin-bottom: var(--spacing-md);
    }

    .index-enroll-content > p:first-of-type {
      color: var(--color-text-on-dark);
      font-size: 1.1rem;
      margin-bottom: var(--spacing-lg);
    }

    .index-enroll-buttons {
      display: flex;
      gap: var(--spacing-md);
      margin-bottom: var(--spacing-lg);
      flex-wrap: wrap;
      justify-content: center;
    }

    .index-enroll-buttons .btn {
      min-width: 250px;
    }

    .index-enroll-guarantee {
      color: var(--color-text-on-dark);
      font-size: 0.95rem;
      margin: 0;
    }

    /* Mobile responsive */
    @media (max-width: 600px) {
      .index-hero .container {
        grid-template-columns: 1fr;
        gap: var(--spacing-lg);
        padding: var(--spacing-lg) 0;
      }

      .index-hero-content h1 {
        font-size: 1.8rem;
      }

      .index-hero-subtitle {
        font-size: 1rem;
      }

      .index-hero-btn {
        align-self: stretch;
      }

      .index-overview {
        padding: var(--spacing-xl) 0;
      }

      .index-overview h2 {
        font-size: 1.6rem;
      }

      .index-curriculum-section {
        padding: var(--spacing-xl) 0;
      }

      .index-module-header {
        padding: var(--spacing-md);
        font-size: 1rem;
      }

      .index-module-number {
        min-width: 36px;
        width: 36px;
        height: 36px;
        font-size: 0.9rem;
      }

      .index-module-content {
        padding: var(--spacing-md);
      }

      .index-testimonials-section {
        padding: var(--spacing-xl) 0;
      }

      .index-enroll-section {
        padding: var(--spacing-xl) 0;
      }

      .index-enroll-buttons {
        flex-direction: column;
      }

      .index-enroll-buttons .btn {
        min-width: auto;
        width: 100%;
      }
    }

    /* Desktop responsive */
    @media (min-width: 601px) {
      .index-hero .container {
        grid-template-columns: 1fr 1fr;
      }

      .index-enroll-buttons {
        flex-direction: row;
      }
    }

